frappe.ui.form.on('Car Repair Request', {
    refresh: function(frm) {
        // Formatter to show Vehicle Model name in Car dropdown
        frappe.form.link_formatters['Vehicle'] = function(value, doc) {
            if (doc.model) {
                return doc.model; // Display the model name
            }
            return value; // fallback
        };
    }
});

frappe.ui.form.on("Car Repair Request", {
    onload(frm) {
        set_car_filter(frm);

        // Override Car field options to show Make + Model
        frm.fields_dict.car.get_query = function() {
            return {
                query: "frappe.client.get_list",
                filters: {},
                fields: ["name", "make", "model"],
                // You can filter by model if needed
            };
        };
    },

    car(frm) {
        if (!frm.doc.car) return;

        frappe.db.get_doc("Vehicle", frm.doc.car).then(vehicle => {
            frm.set_value("license_plate", vehicle.license_plate);
            frm.set_value("chassis_no", vehicle.chassis_no);

            // Get readable make
            frappe.db.get_value("Vehicle Make", vehicle.make, "make", r1 => {
                let make_name = r1 ? r1.make : vehicle.make;

                // Get readable model
                frappe.db.get_value("Vehicle Model", vehicle.model, "model", r2 => {
                    let model_name = r2 ? r2.model : vehicle.model;

                    frm.set_value("make", make_name);
                    frm.set_value("model", model_name);

                    // ✅ Show Make + Model visually in car field without changing underlying value
                    frm.fields_dict.car.set_input(`${make_name} ${model_name}`);
                });
            });
        });
    }
});

// Filter for Car field based on model
function set_car_filter(frm) {
    frm.set_query("car", function() {
        let filters = {};
        if (frm.doc.model) filters.model = frm.doc.model;
        return { filters };
    });
}

