frappe.ui.form.on('Car Repair Damage', {
    status: function(frm, cdt, cdn) {
        check_all_completed(frm);
    },
    car_repair_damage_add: function(frm) {  // when new row is added
        check_all_completed(frm);
    },
    car_repair_damage_remove: function(frm) {  // when row is removed
        check_all_completed(frm);
    }
});

// Function to check all child rows
function check_all_completed(frm) {
    // Replace 'list_of_damage' with your child table fieldname
    let rows = frm.doc.list_of_damage || [];

    // Check if all rows have status Completed
    let all_completed = rows.length > 0 && rows.every(r => (r.status || '').toLowerCase() === 'completed');

    if (all_completed && frm.doc.status !== 'Completed') {
        frm.set_value('status', 'Completed');
    } else if (!all_completed && frm.doc.status === 'Completed') {
        frm.set_value('status', 'In Progress');  // optional
    }
}

