// Create Quotation Button
frappe.ui.form.on("Car Diagnosis", {
    refresh: function(frm) {
        if (!frm.is_new()) {
            frm.add_custom_button(__('Create Quotation'), function() {
                create_erpnext_quotation(frm);
            }, __("Create"));
        }
    }
});

function create_erpnext_quotation(frm) {

    let customer = frm.doc.customer_name;
    let vehicle = frm.doc.vehicle;
    let issues = frm.doc.issues;
    let email = frm.doc.email_id;
    let car_diagnosis = frm.doc.name;

    if (!customer) {
        frappe.msgprint(__('Please select a Customer in Car Diagnosis first.'));
        return;
    }

    frappe.model.with_doctype("Quotation", function() {
        let doc = frappe.model.get_new_doc("Quotation");

        doc.party_name = customer;
        doc.quotation_to = "Customer";
        doc.naming_series = "SAL-QTN-.YYYY.-";
        doc.remarks = `Quotation based on Car Diagnosis: ${frm.doc.name}`;
        doc.custom_car_diagnosis = car_diagnosis;

        if (email) doc.contact_email = email;

        // LOOP DAMAGE TABLE
        if (frm.doc.car_diagnosis_detail && frm.doc.car_diagnosis_detail.length > 0) {
            frm.doc.car_diagnosis_detail.forEach(damage => {
                if (damage.part_required) {

                    let item = frappe.model.add_child(doc, "items");
                    item.item_code = damage.part_required;
                    //item.item_name = damage.part_required;
                    frappe.db.get_value("Item", damage.part_required, "item_name")
            .then(r => {
                if (r && r.message) {
                    frappe.model.set_value(item.doctype, item.name, "item_name", r.message.item_name);
                }
            });

                    // ✅ QUANTITY FROM DIAGNOSIS
                    item.qty = damage.quantity || 1;

                    // RATE
                    item.rate = damage.estimated_cost || 0;

                    // Set UOM
                    frappe.db.get_value("Item", damage.part_required, "stock_uom")
                        .then(r => {
                            if (r && r.message) {
                                item.uom = r.message.stock_uom;
                                frappe.model.set_value(item.doctype, item.name, "uom", r.message.stock_uom);
                            }
                        });
                }
            });
        }

        // ADD ISSUE AS ITEM
        if (issues) {
            let child = frappe.model.add_child(doc, "items");
            child.item_name = issues;
            child.qty = 1;
            child.rate = 0;
        }

        // VEHICLE
        if (vehicle) {
            if ("vehicle" in doc) doc.vehicle = vehicle;
            else if ("custom_vehicle" in doc) doc.custom_vehicle = vehicle;
        }

        frappe.set_route("Form", doc.doctype, doc.name);
    });
}



