frappe.ui.form.on('Car repair', {
    refresh(frm) {
        frm.remove_custom_button(__('Create Invoice'));

        // Show button only if saved & completed
        if (!frm.doc.__islocal && frm.doc.status === 'Completed') {
            frm.add_custom_button(__('Create Invoice'), () => {
                create_sales_invoice(frm);
            });
        }
    }
});

function create_sales_invoice(frm) {

    // ---------------- VALIDATIONS ----------------
    if (!frm.doc.customer_name) {
        frappe.msgprint(__('Please select a Customer.'));
        return;
    }

    if (!frm.doc.list_of_damage || frm.doc.list_of_damage.length === 0) {
        frappe.msgprint(__('No items found in List of Damage.'));
        return;
    }

    if (frm.doc.sales_invoice) {
        frappe.msgprint(__('Sales Invoice already created: {0}', [frm.doc.sales_invoice]));
        return;
    }

    const company = frappe.defaults.get_user_default('Company');
    if (!company) {
        frappe.msgprint(__('Default Company is not set.'));
        return;
    }

    // ---------------- CREATE SALES INVOICE ----------------
    let si = frappe.model.get_new_doc('Sales Invoice');

    si.customer = frm.doc.customer_name;
    si.company = company;
    si.posting_date = frappe.datetime.nowdate();
    si.car_repair = frm.doc.name;          // custom link field
    si.ignore_pricing_rule = 1;
    si.set_posting_time = 1;

    // Clear items just in case
    si.items = [];

    // ---------------- ADD ITEMS ----------------
    frm.doc.list_of_damage.forEach(d => {
        if (!d.part_required) return;

        si.items.push({
            doctype: 'Sales Invoice Item',
            item_code: d.part_required,
            item_name: d.part_required,
            description: d.damage_description || '',
            qty: d.quantity || 1,
            rate: d.estimated_cost || 0
        });
    });

    // ---------------- INSERT & OPEN ----------------
    frappe.db.insert(si)
        .then(doc => {

            // Link invoice back to Car Repair
            frappe.db.set_value(
                'Car repair',
                frm.doc.name,
                'sales_invoice',
                doc.name
            );

            frappe.show_alert({
                message: __('Sales Invoice {0} created successfully', [doc.name]),
                indicator: 'green'
            });

            // Open created Sales Invoice
            frappe.set_route('Form', 'Sales Invoice', doc.name);
        })
        .catch(err => {
            console.error(err);
            frappe.msgprint(__('Failed to create Sales Invoice.<br>{0}', [err.message]));
        });
}

