frappe.ui.form.on("Car Diagnosis", {
    refresh: function(frm) {
        if (frm.doc.customer_name) {
            populate_from_last_repair(frm);
        }

        if (frm.doc.car_repair_request) {
            make_fields_readonly(frm);
        }

        make_images_clickable(frm);
