frappe.ui.form.on('Item', {
    onload_post_render: function(frm) {
        if (frm.dialog) {
            const item_group_field = frm.dialog.fields_dict.item_group;

            if (item_group_field) {
                item_group_field.df.onchange = function() {
                    handleItemGroupChange(frm, frm.dialog);
                };
            }
        }
    },

    item_group: function(frm) {
        handleItemGroupChange(frm, frm);
    }
});

function handleItemGroupChange(frm, context) {
    const doc = context.doc;

    if (doc.item_group && doc.item_group.length >= 4) {
        generateItemCode(frm, context);

        // Set item_name blank
        frappe.model.set_value(doc.doctype, doc.name, 'item_name', '');
    } else {
        frappe.model.set_value(doc.doctype, doc.name, 'item_code', '');
        frappe.model.set_value(doc.doctype, doc.name, 'item_name', '');
    }
}

function generateItemCode(frm, context) {
    const doc = context.doc;
    if (!doc.item_group) return;

    const groupPrefix = doc.item_group.substring(0, 4).toUpperCase();

    frappe.call({
        method: 'frappe.client.get_list',
        args: {
            doctype: 'Item',
            filters: [['item_code', 'like', groupPrefix + '%']],
            fields: ['item_code'],
            order_by: 'item_code desc',
            limit: 1
        },
        callback: function(r) {
            let nextNumber = 1;

            if (r.message && r.message.length > 0) {
                const lastCode = r.message[0].item_code;
                const lastNumber = parseInt(lastCode.substring(4)) || 0;
                nextNumber = lastNumber + 1;
            }

            const formattedNumber = ('0000' + nextNumber).slice(-4);
            const generatedCode = groupPrefix + formattedNumber;

            // Persist code in dialog so it shows in main form after submission
            frappe.model.set_value(doc.doctype, doc.name, 'item_code', generatedCode);

            // Also update dialog field immediately
            if (context.dialog && context.dialog.fields_dict.item_code) {
                context.dialog.fields_dict.item_code.set_value(generatedCode);
            }
        }
    });
}

