frappe.ui.form.on('Car Repair Request', {
    vehicle_pick_up: function(frm) {
        if (frm.doc.vehicle_pick_up) {

            if (navigator.geolocation) {
                navigator.geolocation.getCurrentPosition(
                    async function(position) {
                        const lat = position.coords.latitude;
                        const lng = position.coords.longitude;

                        // Optional: Use OpenStreetMap Nominatim API for reverse geocoding
                        const response = await fetch(`https://nominatim.openstreetmap.org/reverse?format=json&lat=${lat}&lon=${lng}`);
                        const data = await response.json();

                        const address = data.display_name || `${lat}, ${lng}`;

                        // Set pick-up address
                        frm.set_value('pick_up_address', address);
                        frm.set_df_property('pick_up_address', 'read_only', 1);
                    },
                    function(error) {
                        frappe.msgprint(__('Unable to fetch location! Please allow location access.'));
                    }
                );
            } else {
                frappe.msgprint(__('Geolocation is not supported by your browser.'));
            }

        } else {
            // Clear field when unchecked
            frm.set_value('pick_up_address', '');
            frm.set_df_property('pick_up_address', 'read_only', 0);
        }
    },

    onload: function(frm) {
        frm.set_df_property('pick_up_address', 'read_only', frm.doc.vehicle_pick_up ? 1 : 0);
    }
});

