frappe.ui.form.on('Car Repair Request', {
    // When Customer is selected → fetch car and customer details
    customer_name(frm) {
        if (frm.doc.customer_name) {
            // Fetch associated Car (Vehicle)
            frappe.db.get_list('Vehicle', {
                filters: { custom_customer_name: frm.doc.customer_name },
                fields: ['name']
            }).then(records => {
                if (records.length === 1) {
                    frm.set_value('car', records[0].name);
                } else {
                    frm.set_value('car', '');
                }
            });

            // Fetch customer details (email, phone)
            frappe.db.get_value('Customer', frm.doc.customer_name, ['email_id', 'mobile_no'])
                .then(r => {
                    if (r && r.message) {
                        frm.set_value('email', r.message.email_id || '');
                        frm.set_value('phone', r.message.mobile_no || '');
                    }
                });
        } else {
            frm.set_value('car', '');
            frm.set_value('email', '');
            frm.set_value('phone', '');
        }
    },

    // When Car is selected → fetch customer and odometer value
    car(frm) {
        if (frm.doc.car) {
            frappe.db.get_value('Vehicle', frm.doc.car, ['custom_customer_name', 'last_odometer'])
                .then(r => {
                    if (r && r.message) {
                        const customer_name = r.message.custom_customer_name;
                        const last_odometer = r.message.last_odometer;

                        // Set customer name and odometer value
                        frm.set_value('customer_name', customer_name || '');
                        frm.set_value('odometer_value', last_odometer || '');

                        // Fetch customer email and phone
                        if (customer_name) {
                            frappe.db.get_value('Customer', customer_name, ['email_id', 'mobile_no'])
                                .then(r2 => {
                                    if (r2 && r2.message) {
                                        frm.set_value('email', r2.message.email_id || '');
                                        frm.set_value('phone', r2.message.mobile_no || '');
                                    }
                                });
                        }
                    } else {
                        frm.set_value('customer_name', '');
                        frm.set_value('odometer_value', '');
                        frm.set_value('email', '');
                        frm.set_value('phone', '');
                    }
                });
        } else {
            frm.set_value('customer_name', '');
            frm.set_value('odometer_value', '');
            frm.set_value('email', '');
            frm.set_value('phone', '');
        }
