function open_new_customer_dialog(frm) {
    const d = new frappe.ui.Dialog({
        title: 'Create New Customer & Vehicle',
        fields: [
            { fieldname: 'customer_name', label: 'Customer Name', fieldtype: 'Data', reqd: 1 },
            { fieldname: 'email', label: 'Email', fieldtype: 'Data', options: 'Email', reqd: 1 },
            { fieldname: 'phone', label: 'Phone', fieldtype: 'Data', reqd: 1 },
            { fieldname: 'license_plate', label: 'Vehicle Number', fieldtype: 'Data', reqd: 1 },

            // ✅ Make is Link field
            {
                fieldname: 'make',
                label: 'Make',
                fieldtype: 'Link',
                options: 'Vehicle Make',
                reqd: 1
            },

            // ✅ Model is Link field (no filter)
            {
                fieldname: 'model',
                label: 'Model',
                fieldtype: 'Link',
                options: 'Vehicle Model',
                reqd: 1
            }
        ],
        primary_action_label: 'Create',
        primary_action(values) {
            frappe.call({
                method: "car_repair_service.api.car_repair_request.create_customer_and_vehicle",
                args: { data: JSON.stringify(values) },
                callback: function(r) {
                    if (!r.exc && r.message) {
                        frappe.msgprint("✅ Customer and Vehicle created successfully");

                        frm.set_value("customer_name", r.message.customer);
                        frm.set_value("car", r.message.vehicle);
                        frm.set_value("license_plate", r.message.license_plate);
                        frm.set_value("make", r.message.make);
                        frm.set_value("model", r.message.model);
                        frm.set_value("email", r.message.email);
                        frm.set_value("phone", r.message.phone);


                        frm.refresh_fields();
                        d.hide();
                    }
                }
            });
        }
    });

    d.show();
}







