frappe.ui.form.on("Car repair", {
    refresh(frm) {

        frm.fields_dict["list_of_damage"].grid.get_field("part_required").get_query =
            function(doc, cdt, cdn) {

                return {
                    filters: {
                        model: ["=", get_model_id(frm.doc.model)]
                    }
                };
            };

        function get_model_id(model_name) {
            let out = null;

            frappe.call({
                method: "frappe.client.get_value",
                args: {
                    doctype: "Vehicle Model",
                    filters: { model: model_name },
                    fieldname: "name",
                },
                async: false, // IMPORTANT → Allows synchronous return
                callback: function (r) {
                    if (r.message) {
                        out = r.message.name;
                    }
                }
            });

            return out;
        }
    }
});

