frappe.ui.form.on('Car Repair Request', {

    onload: function(frm) {
        if (frm.is_new()) {
            // Always show fields
            frm.set_value('odometer_value', null);
            frm.set_value('odometer_value_current', null);

            // New odometer is editable
            frm.set_df_property('odometer_value', 'read_only', 0);

            // Current odometer is always read-only
            frm.set_df_property('odometer_value_current', 'read_only', 1);
        }
    },

    customer_name: function(frm) {
        if (!frm.doc.customer_name) return;

        frappe.db.get_list('Car Repair Request', {
            filters: {
                customer_name: frm.doc.customer_name,
                name: ['!=', frm.doc.name]
            },
            fields: ['odometer_value'],
            order_by: 'creation desc',
            limit: 1
        }).then(records => {
            if (records.length) {
                const last_odometer = records[0].odometer_value;

                // Display last service odometer in read-only
                frm.set_value('odometer_value_current', last_odometer);
                frm.set_df_property('odometer_value_current', 'read_only', 1);

                // Prefill new odometer for editing
                frm.set_value('odometer_value', last_odometer);
                frm.set_df_property('odometer_value', 'read_only', 0);
            } else {
                // First-time customer: show field as read-only but empty
                frm.set_value('odometer_value_current', null);
                frm.set_value('odometer_value', null);

                frm.set_df_property('odometer_value_current', 'read_only', 1);
                frm.set_df_property('odometer_value', 'read_only', 0);
            }
        });
    },

    refresh: function(frm) {
        // Ensure current odometer is always read-only
        frm.set_df_property('odometer_value_current', 'read_only', 1);
    },

    odometer_value: function(frm) {
        // Optional validation: new odometer must be greater than last
        if (
            frm.doc.odometer_value_current &&
            frm.doc.odometer_value &&
            frm.doc.odometer_value <= frm.doc.odometer_value_current
        ) {
            frappe.msgprint(__('New Odometer value must be greater than previous reading'));
            frm.set_value('odometer_value', null);
        }
    }

});

frappe.ui.form.on("Car Repair Damage", {
    part_required(frm, cdt, cdn) {
        calculate_amount(cdt, cdn);
    },
    quantity(frm, cdt, cdn) {
        calculate_amount(cdt, cdn);
    },
    estimated_cost(frm, cdt, cdn) {
        calculate_amount(cdt, cdn);
    }
});

function calculate_amount(cdt, cdn) {
    let row = locals[cdt][cdn];

    let qty = flt(row.quantity);
    let est_cost = flt(row.estimated_cost);

    if (qty > 0 && est_cost > 0) {
        frappe.model.set_value(cdt, cdn, "amount", qty * est_cost);
    } else {
        frappe.model.set_value(cdt, cdn, "amount", 0);
    }
}

