frappe.ui.form.on('Car Repair Request', {

    onload(frm) {
        // Fetch pickup data whenever appointment exists
        if (frm.doc.appointment) {

            frappe.call({
                method: "frappe.client.get",
                args: {
                    doctype: "Book Appointment",
                    name: frm.doc.appointment
                },
                callback(r) {
                    if (r.message) {
                        const appt = r.message;

                        // 🚗 Fetch Vehicle Pickup Data
                        frm.set_value("vehicle_pickup_required", appt.vehicle_pickup_required);
                        frm.set_value("pickup_address", appt.pickup_address);
                        frm.set_value("same_as_pick_up_address", appt.same_as_pick_up_address || 0);
                        frm.set_value("drop_address", appt.drop_address);
                        frm.set_value("assigned_to", appt.assigned_to);

                        // Apply visibility + mandatory logic
                        frm.trigger("vehicle_pickup_required");
                    }
                }
            });
        }
    },

    vehicle_pickup_required(frm) {
        if (frm.doc.vehicle_pickup_required === 'Yes, Pickup my vehicle') {

            frm.toggle_display('pickup_address', true);
            frm.toggle_display('same_as_pick_up_address', true);
            frm.toggle_display('drop_address', true);
            frm.toggle_display('assigned_to', true);

            frm.set_df_property('pickup_address', 'reqd', 1);
            frm.set_df_property('drop_address', 'reqd', 1);
            frm.set_df_property('assigned_to', 'reqd', 1);

        } else {

            frm.toggle_display('pickup_address', false);
            frm.toggle_display('same_as_pick_up_address', false);
            frm.toggle_display('drop_address', false);
            frm.toggle_display('assigned_to', false);

            frm.set_df_property('pickup_address', 'reqd', 0);
            frm.set_df_property('drop_address', 'reqd', 0);
            frm.set_df_property('assigned_to', 'reqd', 0);

            frm.set_value('pickup_address', '');
            frm.set_value('same_as_pick_up_address', 0);
            frm.set_value('drop_address', '');
            frm.set_value('assigned_to', '');
        }
    },

    pickup_address(frm) {
        if (frm.doc.same_as_pick_up_address) {
            frm.set_value('drop_address', frm.doc.pickup_address);
        }
    },

    same_as_pick_up_address(frm) {
        if (frm.doc.same_as_pick_up_address) {
            frm.set_value('drop_address', frm.doc.pickup_address);
        } else {
            frm.set_value('drop_address', '');
        }
    },

    refresh(frm) {
        frm.trigger('vehicle_pickup_required');
    }
});
